diff --git a/test/unit/route-normalize.test.ts b/test/unit/route-normalize.test.ts
new file mode 100644
index 0000000..2243241
--- /dev/null
+++ b/test/unit/route-normalize.test.ts
@@ -0,0 +1,148 @@
+import { describe, expect, it } from "vitest";
+import { H3 } from "../../src/h3.ts";
+import { removeRoute } from "../../src/utils/route.ts";
+import { normalizeRoute } from "../../src/utils/internal/path.ts";
+
+// `on()` used to normalize a route pattern with `new URL(route, "http://_")`
+// while `use(route, mw)` normalized it with `canonicalPathname` alone. The two
+// disagreed on every pattern the URL serializer touches, so a guard registered
+// with the *same source string* as the route it guards could match nothing
+// while the route stayed reachable — guards failing open. Both now share
+// `normalizeRoute`; this pins what that shape is.
+const CASES: Array<[source: string, registered: string]> = [
+  // Plain pathnames
+  ["/admin", "/admin"],
+  ["admin", "/admin"],
+  ["", "/"],
+  ["/", "/"],
+  // An authority is not swallowed: `//admin` used to register at `/`, mounting
+  // a handler at the root from a pattern that reads as scoped.
+  ["//admin", "//admin"],
+  // Dot segments resolve the way the URL parser resolves them in a request path
+  ["/admin/../admin", "/admin"],
+  ["/a/./b", "/a/b"],
+  ["/a/.", "/a/"],
+  ["/a/..", "/"],
+  ["/../admin", "/admin"],
+  ["/a/%2e%2e/b", "/b"],
+  // Characters a request pathname always carries percent-encoded
+  ["/café/**", "/caf%C3%A9/**"],
+  ["/a b/**", "/a%20b/**"],
+  ['/x"y', "/x%22y"],
+  ["/x<y>z", "/x%3Cy%3Ez"],
+  ["/x`y", "/x%60y"],
+  ["/x#y", "/x%23y"],
+  ["/😀", "/%F0%9F%98%80"],
+  // rou3 pattern syntax survives verbatim. `\` especially: the URL parser
+  // turned it into `/`, silently rewriting `/user/:id(\d+)` to `/user/:id(/d+)`.
+  [String.raw`/user/:id(\d+)`, String.raw`/user/:id(\d+)`],
+  [String.raw`/a\:b`, String.raw`/a\:b`],
+  ["/a/{x}", "/a/{x}"],
+  ["/u/:id?", "/u/:id?"],
+  ["/files/**:rest", "/files/**:rest"],
+  ["/x^y", "/x^y"],
+  // Needless escapes are still canonicalized, matching what `event.url.pathname`
+  // is canonicalized to. The escapes that are *not* needless stay opaque, which
+  // is how a literal `^`/`?`/`{`/`}` is spelled in a pattern.
+  ["/%40handle", "/@handle"],
+  ["/x%5Ey", "/x%5Ey"],
+  ["/x%3Fy", "/x%3Fy"],
+];
+
+describe("normalizeRoute", () => {
+  it.each(CASES)("%j -> %j", (source, registered) => {
+    expect(normalizeRoute(source)).toBe(registered);
+  });
+
+  it.each(CASES)("%j -> %j is a fixed point", (_source, registered) => {
+    expect(normalizeRoute(registered)).toBe(registered);
+  });
+
+  it("rejects a pattern that is a URL, instead of swallowing its authority", () => {
+    for (const url of [
+      "http://evil.com/admin",
+      "https://evil.com/admin",
+      "HTTP://evil.com/admin",
+      "file:///etc/passwd",
+    ]) {
+      expect(() => normalizeRoute(url), url).toThrow(/Route patterns are pathnames/);
+    }
+  });
+});
+
+describe("route registration", () => {
+  it.each(CASES)("get(%j) registers %j", (source, registered) => {
+    const app = new H3();
+    app.get(source, () => "ok");
+    expect(app["~routes"][0].route).toBe(registered);
+  });
+
+  it("get() rejects a pattern that is a URL", () => {
+    const app = new H3();
+    expect(() => app.get("http://evil.com/admin", () => "ok")).toThrow(
+      /Route patterns are pathnames/,
+    );
+  });
+
+  it("use() rejects a pattern that is a URL", () => {
+    const app = new H3();
+    expect(() => app.use("http://evil.com/admin", () => "ok")).toThrow(
+      /Route patterns are pathnames/,
+    );
+  });
+
+  it.each(CASES)("removeRoute(%j) removes the route registered as %j", (source, registered) => {
+    const app = new H3();
+    app.get(source, () => "ok");
+    removeRoute(app, "GET", source);
+    expect(app["~routes"]).toHaveLength(0);
+    expect(normalizeRoute(source)).toBe(registered);
+  });
+});
+
+// A guard registered with the same source string as the route it guards must
+// always fire. These run through `app.request()` rather than `describeMatrix`
+// because the node test client resolves `//admin` as a protocol-relative URL
+// (host `admin`) before it ever reaches h3; matching itself is target-independent.
+describe("guard parity", () => {
+  const SCOPES: Array<{ route: string; guard: string; path: string }> = [
+    { route: "/café/secret", guard: "/café/**", path: "/caf%C3%A9/secret" },
+    { route: "/a b/secret", guard: "/a b/**", path: "/a%20b/secret" },
+    { route: "//admin", guard: "//admin", path: "//admin" },
+    { route: "/admin/../admin", guard: "/admin/../admin", path: "/admin" },
+    { route: "/x<y>", guard: "/x<y>", path: "/x%3Cy%3E" },
+    { route: "/x%5Ey", guard: "/x%5Ey", path: "/x^y" },
+    { route: "/%40handle/**", guard: "/%40handle/**", path: "/@handle/x" },
+    // `{}` was percent-encoded by the URL pass, registering an unreachable
+    // route while the guard (kept literal) still fired.
+    { route: "/a/{-:x}", guard: "/a/{-:x}", path: "/a/-x" },
+    // A unicode literal inside a rou3 group encodes to the form the request
+    // carries, so the group still matches.
+    { route: "/user/:id(café)", guard: "/user/:id(café)", path: "/user/caf%C3%A9" },
+    { route: String.raw`/user/:id(\d+)`, guard: String.raw`/user/:id(\d+)`, path: "/user/42" },
+  ];
+
+  it.each(SCOPES)("$guard guards $path", async ({ route, guard, path }) => {
+    const app = new H3();
+    app.use(guard, () => "DENIED");
+    app.all(route, () => "ALLOWED");
+    const res = await app.request(path);
+    expect(await res.text()).toBe("DENIED");
+  });
+
+  it("keeps a rou3 escape intact: `:id(\\d+)` does not match a non-numeric id", async () => {
+    const app = new H3();
+    app.get(String.raw`/user/:id(\d+)`, (event) => event.context.params!.id);
+
+    expect(await (await app.request("/user/42")).text()).toBe("42");
+    expect((await app.request("/user/abc")).status).toBe(404);
+  });
+
+  it("does not mount a `//admin` pattern at the root", async () => {
+    const app = new H3();
+    app.get("//admin", () => "admin");
+
+    expect(await (await app.request("//admin")).text()).toBe("admin");
+    expect((await app.request("/")).status).toBe(404);
+  });
+});

diff --git a/test/cache.test.ts b/test/cache.test.ts
new file mode 100644
index 0000000..9b6ddb1
--- /dev/null
+++ b/test/cache.test.ts
@@ -0,0 +1,226 @@
+import { createMemoryStorage, defineCachedHandler } from "ocache";
+import {
+  HTTPError,
+  defineHandler,
+  handleCacheHeaders,
+  toResponse,
+  withCacheIsolation,
+} from "../src/index.ts";
+import { H3Event } from "../src/index.ts";
+import { describeMatrix } from "./_setup.ts";
+
+describeMatrix("withCacheIsolation", (t, { it, expect }) => {
+  // A handler-level cache the way frameworks such as Nitro build one (h3js/h3#1607).
+  const createCached = (handler: (event: H3Event) => unknown, opts?: { varies?: string[] }) =>
+    withCacheIsolation(
+      defineCachedHandler(handler, {
+        storage: createMemoryStorage(),
+        maxAge: 60,
+        ...opts,
+        toResponse: (value, event) => toResponse(value, event as H3Event),
+        handleCacheHeaders: (event, conditions) => handleCacheHeaders(event as H3Event, conditions),
+      }),
+    );
+
+  it("keeps middleware-staged headers out of the cache entry", async () => {
+    const cached = createCached(() => "hello");
+    t.app.use((event) => {
+      const echo = event.req.headers.get("x-echo");
+      if (echo) event.res.headers.set("x-echo", echo);
+    });
+    t.app.get(
+      "/cached",
+      defineHandler((event) => cached(event)),
+    );
+
+    const miss = await t.fetch("/cached", { headers: { "x-echo": "a" } });
+    expect(miss.headers.get("x-echo")).toBe("a");
+    expect(await miss.text()).toBe("hello");
+
+    const hit = await t.fetch("/cached");
+    expect(hit.headers.get("x-echo")).toBeNull();
+    expect(await hit.text()).toBe("hello");
+
+    const other = await t.fetch("/cached", { headers: { "x-echo": "b" } });
+    expect(other.headers.get("x-echo")).toBe("b");
+  });
+
+  it("keeps middleware-staged cookies out of the cache entry", async () => {
+    const cached = createCached(() => "hello");
+    t.app.use((event) => {
+      const user = event.req.headers.get("x-user");
+      if (user) event.res.headers.append("set-cookie", `user=${user}`);
+    });
+    t.app.get("/cached", cached);
+
+    const miss = await t.fetch("/cached", { headers: { "x-user": "alice" } });
+    expect(miss.headers.get("set-cookie")).toBe("user=alice");
+    const hit = await t.fetch("/cached");
+    expect(hit.headers.get("set-cookie")).toBeNull();
+  });
+
+  it("still caches a route behind middleware that stages `vary: origin`", async () => {
+    let calls = 0;
+    const cached = createCached(() => `hello ${++calls}`);
+    t.app.use((event) => {
+      event.res.headers.set("vary", "origin");
+    });
+    t.app.get("/cached", cached);
+
+    const first = await t.fetch("/cached");
+    expect(await first.text()).toBe("hello 1");
+    expect(first.headers.get("vary")).toBe("origin");
+    const second = await t.fetch("/cached");
+    expect(await second.text()).toBe("hello 1");
+    expect(second.headers.get("vary")).toBe("origin");
+  });
+
+  it("does not store a response that varies on a header the cache isn't keyed on", async () => {
+    const cached = createCached((event) => `hello in ${event.context.lang}`);
+    t.app.use((event) => {
+      event.context.lang = event.req.headers.get("accept-language") ?? "en";
+      event.res.headers.set("vary", "origin, accept-language");
+    });
+    t.app.get("/cached", cached);
+
+    const en = await t.fetch("/cached", { headers: { "accept-language": "en" } });
+    expect(await en.text()).toBe("hello in en");
+    const fr = await t.fetch("/cached", { headers: { "accept-language": "fr" } });
+    expect(await fr.text()).toBe("hello in fr");
+    expect(fr.headers.get("vary")).toBe("accept-language, origin");
+  });
+
+  it("caches per value of a staged `Vary` the cache is keyed on", async () => {
+    let calls = 0;
+    const cached = createCached((event) => `hello in ${event.context.lang} (${++calls})`, {
+      varies: ["accept-language"],
+    });
+    t.app.use((event) => {
+      event.context.lang = event.req.headers.get("accept-language") ?? "en";
+      event.res.headers.set("vary", "accept-language");
+    });
+    t.app.get("/cached", cached);
+
+    const fetchLang = async (lang: string) =>
+      (await t.fetch("/cached", { headers: { "accept-language": lang } })).text();
+    expect(await fetchLang("en")).toBe("hello in en (1)");
+    expect(await fetchLang("fr")).toBe("hello in fr (2)");
+    expect(await fetchLang("en")).toBe("hello in en (1)");
+  });
+
+  it("keeps the cached handler's own methods", async () => {
+    let calls = 0;
+    let url = "";
+    const cached = createCached((event) => {
+      url = event.req.url;
+      return `hello ${++calls}`;
+    });
+    t.app.get("/cached", cached);
+
+    expect(await (await t.fetch("/cached")).text()).toBe("hello 1");
+    expect(await (await t.fetch("/cached")).text()).toBe("hello 1");
+    expect(typeof cached.expire).toBe("function");
+    expect(typeof cached.resolveKeys).toBe("function");
+    await cached.invalidate(new H3Event(new Request(url)));
+    expect(await (await t.fetch("/cached")).text()).toBe("hello 2");
+  });
+
+  it("does not store a response that middleware staged as `private`", async () => {
+    let calls = 0;
+    const cached = createCached(() => `hello ${++calls}`);
+    t.app.use((event) => {
+      event.res.headers.set("cache-control", "private, no-store");
+    });
+    t.app.get("/cached", cached);
+
+    expect(await (await t.fetch("/cached")).text()).toBe("hello 1");
+    expect(await (await t.fetch("/cached")).text()).toBe("hello 2");
+  });
+
+  it("sends a middleware-staged `private` to the client", async () => {
+    // `handleCacheHeaders` would otherwise replace it with `public`, and a CDN
+    // in front of the app could store the page middleware kept private.
+    const cached = createCached(() => "hello");
+    t.app.use((event) => {
+      if (event.req.headers.has("x-user")) {
+        event.res.headers.set("cache-control", "private, no-store");
+      }
+    });
+    t.app.get("/cached", cached);
+
+    const user = await t.fetch("/cached", { headers: { "x-user": "alice" } });
+    expect(user.headers.get("cache-control")).toBe("private, no-store");
