+    expect(
+      getPublicAssetRoutes([asset({ baseURL: "/build", fallthrough: false, maxAge: 3600 })], {
+        baseURL: "/",
+        routeRules: {},
+      })
+    ).toEqual([{ src: "/build/(.*)", cacheControl: "public, max-age=3600, immutable" }]);
+  });
